DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.reserve_measured_media(uuid,uuid,uuid,text,text,bigint,boolean)'::regprocedure) INTO definition; IF position('cardinality(seg)<4' in definition)=0 THEN RAISE EXCEPTION 'Unexpected path validation'; END IF; EXECUTE replace(definition,'cardinality(seg)<4','cardinality(seg)<3'); END $$; REVOKE ALL ON FUNCTION public.reserve_measured_media(uuid,uuid,uuid,text,text,bigint,boolean) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.reserve_measured_media(uuid,uuid,uuid,text,text,bigint,boolean) TO service_role;